                .Where(p => p.TenantId == tenantId && purchaseIds.Contains(p.Id))
                .Include(p => p.Supplier)
                .Include(p => p.Items)
                .Include(p => p.Payments)
                .OrderBy(p => p.PurchasedAt).ThenBy(p => p.CreatedAt)
                .ToListAsync();

            var allSupplierPurchases = await db.Purchases.AsNoTracking()
                .Where(p => p.TenantId == tenantId && p.SupplierId == supplierId && p.Status == "Posted")
                .Include(p => p.Payments)
                .ToListAsync();

            var totalAllocated = Money(existingPayments.Sum(p => p.Amount));
            var remainingBalance = Money(allSupplierPurchases.Sum(p => p.TotalAmount - p.Payments.Where(x => !x.IsReversed).Sum(x => x.Amount)));

            if (write != null) await write.CommitAsync();

            return ApiResult<SupplierAccountPaymentResultDto>.Ok(new(
                TotalAmountPaid: Money(request.Amount),
                TotalAllocated: totalAllocated,
                RemainingBalance: remainingBalance,
                AffectedPurchases: replayPurchases.Select(MapPurchase).ToList()
            ));
        }

        var supplier = await db.Suppliers.FirstOrDefaultAsync(s => s.TenantId == tenantId && s.Id == supplierId && s.Status == "Active");
        if (supplier == null) return ApiResult<SupplierAccountPaymentResultDto>.Fail("Supplier not found.");

        var openPurchases = await db.Purchases
            .Where(p => p.TenantId == tenantId && p.SupplierId == supplierId && p.Status == "Posted")
            .Include(p => p.Supplier)
            .Include(p => p.Items)
            .Include(p => p.Payments)
            .OrderBy(p => p.PurchasedAt)
            .ThenBy(p => p.CreatedAt)
            .ToListAsync();

        var unpaidPurchases = openPurchases.Where(p => Money(p.TotalAmount - p.Payments.Where(x => !x.IsReversed).Sum(x => x.Amount)) > 0).ToList();
        var totalOutstanding = Money(unpaidPurchases.Sum(p => p.TotalAmount - p.Payments.Where(x => !x.IsReversed).Sum(x => x.Amount)));
        if (totalOutstanding <= 0)
            return ApiResult<SupplierAccountPaymentResultDto>.Fail("Supplier does not have any outstanding balance.");

        if (request.Amount > totalOutstanding)
            return ApiResult<SupplierAccountPaymentResultDto>.Fail($"Payment amount cannot exceed the total outstanding balance of {totalOutstanding}.");

        var remainingToAllocate = Money(request.Amount);
        var paidAt = Utc(request.PaidAt ?? DateTime.UtcNow);
        var affectedPurchases = new List<PurchaseDto>();
        var paymentIndex = 1;

        foreach (var purchase in unpaidPurchases)
        {
            if (remainingToAllocate <= 0) break;

            var purchasePaid = Money(purchase.Payments.Where(x => !x.IsReversed).Sum(x => x.Amount));
            var purchaseRemaining = Money(purchase.TotalAmount - purchasePaid);
            var paymentPortion = Math.Min(remainingToAllocate, purchaseRemaining);

            var payment = new PurchasePayment
            {
                Id = Guid.NewGuid(),
                TenantId = tenantId,
                PurchaseId = purchase.Id,
                SupplierId = supplier.Id,
                Amount = Money(paymentPortion),
                Currency = purchase.Currency,
                Method = NormalizeMethod(request.Method),
                Reference = Clean(request.Reference) ?? $"Account Payment ({purchase.PurchaseNumber})",
                Notes = Clean(request.Notes),
                IdempotencyKey = $"{idempotencyKey}:{paymentIndex++}",
                RequestHash = requestHash,
                PaidAt = paidAt,
                CreatedAt = DateTime.UtcNow,
                Supplier = supplier,
                Purchase = purchase
            };

            purchase.Payments.Add(payment);
            db.PurchasePayments.Add(payment);
            purchase.UpdatedAt = DateTime.UtcNow;

            remainingToAllocate = Money(remainingToAllocate - paymentPortion);
            affectedPurchases.Add(MapPurchase(purchase));
        }

        await db.SaveChangesAsync();
        if (write != null) await write.CommitAsync();

        var newTotalOutstanding = Money(totalOutstanding - request.Amount);
        return ApiResult<SupplierAccountPaymentResultDto>.Ok(new(
            TotalAmountPaid: Money(request.Amount),
            TotalAllocated: Money(request.Amount - remainingToAllocate),
            RemainingBalance: newTotalOutstanding,
            AffectedPurchases: affectedPurchases
        ));
    }

    public async Task<ApiResult<List<string>>> GetDistinctProductUnitsAsync(Guid tenantId)
    {
        var dbUnits = await db.Products.AsNoTracking()
            .Where(p => p.TenantId == tenantId && !string.IsNullOrWhiteSpace(p.Unit))
            .Select(p => p.Unit.Trim())
            .Distinct()
            .ToListAsync();

        var commonPresets = new[] { "item", "cái", "kg", "g", "box", "hộp", "bag", "bao", "túi", "bottle", "chai", "can", "lon", "pack", "gói", "m", "hour", "giờ", "set", "bộ" };

        var merged = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
        foreach (var u in dbUnits) if (!string.IsNullOrWhiteSpace(u)) merged.Add(u);
        foreach (var p in commonPresets) merged.Add(p);

        return ApiResult<List<string>>.Ok(merged.OrderBy(u => u).ToList());
    }

    public async Task<ApiResult<List<DashboardAttentionItemDto>>> GetDashboardAttentionItemsAsync(Guid tenantId)
    {
        var items = new List<DashboardAttentionItemDto>();
        var now = DateTime.UtcNow;
        var currency = await Currency(tenantId);

        // 1. Out of stock products (TrackInventory = true && StockQuantity <= 0)
        var outOfStockCount = await db.Products.AsNoTracking()
            .CountAsync(p => p.TenantId == tenantId && p.IsActive && p.TrackInventory && p.StockQuantity <= 0);

        if (outOfStockCount > 0)
        {
            var samples = await db.Products.AsNoTracking()
                .Where(p => p.TenantId == tenantId && p.IsActive && p.TrackInventory && p.StockQuantity <= 0)
                .OrderBy(p => p.StockQuantity)
                .Take(2)
                .Select(p => p.Name)
                .ToListAsync();
            var firstNames = string.Join(", ", samples);
            items.Add(new DashboardAttentionItemDto(
                Id: "attention_out_of_stock",
                Type: "out_of_stock",
                Severity: "urgent",
                Title: $"{outOfStockCount} {(outOfStockCount == 1 ? "product" : "products")} out of stock",
                Subtitle: $"Restock needed for {firstNames}{(outOfStockCount > 2 ? $" and {outOfStockCount - 2} more" : "")}.",
                Count: outOfStockCount,
                ActionLabel: "Restock items",
                ActionRoute: "/products?stock=out_of_stock",
                ActionKey: "out_of_stock"
            ));
        }

        // 2. Low stock products (TrackInventory = true && StockQuantity > 0 && StockQuantity <= (MinStockLevel ?? 5))
        var lowStockCount = await db.Products.AsNoTracking()
            .CountAsync(p => p.TenantId == tenantId && p.IsActive && p.TrackInventory && p.StockQuantity > 0 && p.StockQuantity <= (p.MinStockLevel ?? 5));

        if (lowStockCount > 0)
        {
            var lowStockSamples = await db.Products.AsNoTracking()
                .Where(p => p.TenantId == tenantId && p.IsActive && p.TrackInventory && p.StockQuantity > 0 && p.StockQuantity <= (p.MinStockLevel ?? 5))
                .Take(2)
                .Select(p => p.Name)
                .ToListAsync();
            var names = string.Join(", ", lowStockSamples);

            items.Add(new DashboardAttentionItemDto(
                Id: "attention_low_stock",
                Type: "low_stock",
                Severity: "warn",
                Title: $"{lowStockCount} {(lowStockCount == 1 ? "product" : "products")} running low",
                Subtitle: $"Low threshold reached: {names}{(lowStockCount > 2 ? $" and {lowStockCount - 2} others" : "")}.",
                Count: lowStockCount,
                ActionLabel: "Review stock",
                ActionRoute: "/products?stock=low_stock",
                ActionKey: "low_stock"
            ));
        }

        // 3. Pending AI actions (AiActions with PendingConfirmation and not expired)
        var pendingActions = await db.AiActions.AsNoTracking()
            .Where(a => a.TenantId == tenantId && a.Status == AiActionStatuses.PendingConfirmation && a.ExpiresAt > now)
            .OrderByDescending(a => a.CreatedAt)
            .ToListAsync();

        if (pendingActions.Count > 0)
        {
            items.Add(new DashboardAttentionItemDto(
                Id: "attention_pending_ai_actions",
                Type: "pending_ai_actions",
                Severity: "warn",
                Title: $"{pendingActions.Count} AI {(pendingActions.Count == 1 ? "draft" : "drafts")} awaiting confirmation",
                Subtitle: "Review staged proposals before they are committed.",
                Count: pendingActions.Count,
                ActionLabel: "Review drafts",
                ActionRoute: "/agent",
                ActionKey: "pending_ai_actions"
            ));
        }

        // 4. Supplier bills due or overdue (Posted purchases with outstanding balance and DueDate <= now + 3 days)
        var cutoff = now.AddDays(3);
        var openPurchases = await db.Purchases.AsNoTracking()
            .Where(p => p.TenantId == tenantId && p.Status == "Posted")
            .Include(p => p.Supplier)
            .Include(p => p.Payments)
            .ToListAsync();

        var unpaidPurchasesWithDue = openPurchases
            .Select(p => new
            {
                Purchase = p,
                Paid = Money(p.Payments.Where(x => !x.IsReversed).Sum(x => x.Amount)),
                Balance = Money(p.TotalAmount - p.Payments.Where(x => !x.IsReversed).Sum(x => x.Amount)),
                EffectiveDue = p.DueDate ?? (p.Supplier != null && p.Supplier.PaymentTermsDays.HasValue ? (DateTime?)p.PurchasedAt.AddDays(p.Supplier.PaymentTermsDays.Value) : null)
            })
            .Where(x => x.Balance > 0 && x.EffectiveDue.HasValue && x.EffectiveDue.Value <= cutoff)
            .OrderBy(x => x.EffectiveDue)
            .ToList();

        if (unpaidPurchasesWithDue.Count > 0)
        {
            var overdue = unpaidPurchasesWithDue.Where(x => x.EffectiveDue!.Value < now).ToList();
            var isOverdue = overdue.Count > 0;
            var targetList = isOverdue ? overdue : unpaidPurchasesWithDue;
            var totalUnpaid = targetList.Sum(x => x.Balance);
            var firstItem = targetList.First();

            items.Add(new DashboardAttentionItemDto(
                Id: "attention_supplier_bill_due",
                Type: "supplier_bill_due",
                Severity: isOverdue ? "urgent" : "warn",
                Title: isOverdue
                    ? $"{overdue.Count} supplier {(overdue.Count == 1 ? "bill" : "bills")} overdue"
                    : $"{unpaidPurchasesWithDue.Count} supplier {(unpaidPurchasesWithDue.Count == 1 ? "bill" : "bills")} due soon",
                Subtitle: $"Total {totalUnpaid:N0} {currency}. Nearest: {firstItem.Purchase.Supplier?.Name ?? "Supplier"} ({firstItem.Balance:N0} {currency}).",
                Count: targetList.Count,
                ActionLabel: "Pay supplier",
                ActionRoute: "/suppliers",
                ActionKey: "pay_supplier",
                Metadata: new { supplierId = firstItem.Purchase.SupplierId, supplierName = firstItem.Purchase.Supplier?.Name, amount = firstItem.Balance }
            ));
        }

        // 5. Customer overdue receivables (open sales older than 30 days)
        var openSales = await db.Sales.AsNoTracking()
            .Where(s => s.TenantId == tenantId && s.Status == SaleStatuses.Posted)
            .Include(s => s.Customer)
            .Include(s => s.Payments)
            .ToListAsync();

        var overdueCustomerSales = openSales
            .Select(s => new
            {
                Sale = s,
                Balance = Money(s.TotalAmount - s.Payments.Where(p => !p.IsReversed).Sum(p => p.Amount)),
                AgeDays = (now - s.SoldAt).TotalDays
            })
            .Where(x => x.Balance > 0 && x.AgeDays >= 30)
            .OrderByDescending(x => x.Balance)
            .ToList();

        if (overdueCustomerSales.Count > 0)
        {
            var top = overdueCustomerSales.First();
            var totalCustomerOverdue = overdueCustomerSales.Sum(x => x.Balance);
            items.Add(new DashboardAttentionItemDto(
                Id: "attention_customer_overdue",
                Type: "customer_overdue",
                Severity: "warn",
                Title: $"{overdueCustomerSales.Count} overdue {(overdueCustomerSales.Count == 1 ? "receivable" : "receivables")} (>30 days)",
                Subtitle: $"Total {totalCustomerOverdue:N0} {currency}. Top debtor: {top.Sale.Customer?.Name ?? "Customer"} ({top.Balance:N0} {currency}).",
                Count: overdueCustomerSales.Count,
                ActionLabel: "View receivables",
                ActionRoute: "/customers",
                ActionKey: "customer_overdue"
            ));
        }

        // 6. Unusual activity (e.g. sale today > 3x trailing 30-day average)
        var thirtyDaysAgo = now.AddDays(-30);
        var pastSales = await db.Sales.AsNoTracking()
            .Where(s => s.TenantId == tenantId && s.Status == SaleStatuses.Posted && s.SoldAt >= thirtyDaysAgo && s.SoldAt < now.Date)
            .Select(s => s.TotalAmount)
            .ToListAsync();

        if (pastSales.Count >= 5)
        {
            var avgSale = pastSales.Average();
            var todayBigSale = await db.Sales.AsNoTracking()
                .Where(s => s.TenantId == tenantId && s.Status == SaleStatuses.Posted && s.SoldAt >= now.Date && s.TotalAmount >= avgSale * 3m && s.TotalAmount > 0)
                .OrderByDescending(s => s.TotalAmount)
                .Include(s => s.Customer)
                .FirstOrDefaultAsync();

            if (todayBigSale != null)
            {
                items.Add(new DashboardAttentionItemDto(
                    Id: "attention_unusual_activity",
                    Type: "unusual_activity",
                    Severity: "info",
                    Title: "High-value sale recorded today",
                    Subtitle: $"{todayBigSale.SaleNumber} to {todayBigSale.Customer?.Name ?? "Customer"} ({todayBigSale.TotalAmount:N0} {currency}) is over 3x your daily average.",
                    Count: 1,
                    ActionLabel: "View sale",
                    ActionRoute: "/sales",
                    ActionKey: "unusual_activity"
                ));
            }
        }

        // 7. Recurring expenses due
        var dueRecurringTemplates = await db.RecurringExpenseTemplates.AsNoTracking()
            .Where(t => t.TenantId == tenantId && t.IsActive && t.NextDueDate <= now)
            .ToListAsync();
        if (dueRecurringTemplates.Count > 0)
        {
            var firstDue = dueRecurringTemplates.First();
            items.Add(new DashboardAttentionItemDto(
                Id: "attention_recurring_expense_due",
                Type: "recurring_expense_due",
                Severity: "warn",
                Title: $"{dueRecurringTemplates.Count} recurring expense{(dueRecurringTemplates.Count == 1 ? "" : "s")} due",
                Subtitle: $"Upcoming: {firstDue.Category} ({firstDue.Amount:N0} {currency}). Generate or confirm drafts.",
                Count: dueRecurringTemplates.Count,
                ActionLabel: "Review recurring",
                ActionRoute: "/expenses?tab=recurring",
                ActionKey: "recurring_expense_due"
            ));
        }

        return ApiResult<List<DashboardAttentionItemDto>>.Ok(items);
    }

    public async Task<ApiResult<List<DashboardInsightDto>>> GetDashboardInsightsAsync(Guid tenantId)
    {
        var insights = new List<DashboardInsightDto>();
        var now = DateTime.UtcNow;
        var currency = await Currency(tenantId);

        // 1. Week-over-week sales change
        var diff = (7 + (int)now.DayOfWeek - (int)DayOfWeek.Monday) % 7;
        var thisWeekStart = now.Date.AddDays(-diff);
        var lastWeekStart = thisWeekStart.AddDays(-7);
        var lastWeekEnd = thisWeekStart;

        var thisWeekSales = await db.Sales.AsNoTracking()
            .Where(s => s.TenantId == tenantId && s.Status == SaleStatuses.Posted && s.SoldAt >= thisWeekStart)
            .SumAsync(s => (decimal?)s.TotalAmount) ?? 0m;

        var lastWeekSales = await db.Sales.AsNoTracking()
            .Where(s => s.TenantId == tenantId && s.Status == SaleStatuses.Posted && s.SoldAt >= lastWeekStart && s.SoldAt < lastWeekEnd)
            .SumAsync(s => (decimal?)s.TotalAmount) ?? 0m;

        if (thisWeekSales > 0 || lastWeekSales > 0)
        {
            if (lastWeekSales > 0)
            {
                var delta = ((thisWeekSales - lastWeekSales) / lastWeekSales) * 100m;
                var trend = delta >= 0 ? "up" : "down";
                var sign = delta >= 0 ? "+" : "";
                insights.Add(new DashboardInsightDto(
                    Id: "insight_sales_trend",
                    Type: "sales_trend",
                    Headline: $"Sales are {sign}{delta:F1}% compared to last week",
                    Detail: $"Recorded {thisWeekSales:N0} {currency} this week vs. {lastWeekSales:N0} {currency} last week.",
                    Trend: trend,
                    MetricValue: Math.Round(delta, 1)
                ));
            }
            else
            {
                insights.Add(new DashboardInsightDto(
                    Id: "insight_sales_trend",
                    Type: "sales_trend",
                    Headline: $"This week's sales: {thisWeekSales:N0} {currency}",
                    Detail: "No recorded sales during the previous week to compare.",
                    Trend: "neutral",
                    MetricValue: thisWeekSales
                ));
            }
        }

        // 2. Fast-moving product in the last 7 days
        var sevenDaysAgo = now.AddDays(-7);
        var topProduct = await db.SaleItems.AsNoTracking()
            .Where(si => si.TenantId == tenantId && si.Sale != null && si.Sale.Status == SaleStatuses.Posted && si.Sale.SoldAt >= sevenDaysAgo)
            .GroupBy(si => new { si.ProductId, si.ProductName, si.Unit })
            .Select(g => new { g.Key.ProductId, g.Key.ProductName, g.Key.Unit, TotalQuantity = g.Sum(x => x.Quantity), TotalRevenue = g.Sum(x => x.LineTotal) })
            .OrderByDescending(x => x.TotalQuantity)
            .FirstOrDefaultAsync();

        if (topProduct != null && topProduct.TotalQuantity > 0)
        {
            insights.Add(new DashboardInsightDto(
                Id: "insight_top_mover",
                Type: "top_mover",
                Headline: $"Top seller: {topProduct.ProductName}",
                Detail: $"{topProduct.TotalQuantity:N0} {topProduct.Unit} sold in the last 7 days generating {topProduct.TotalRevenue:N0} {currency}.",
                Trend: "up",
                MetricValue: topProduct.TotalQuantity
            ));
        }

        // 3. Projected cash shortfall or health check (Cash collected this week vs. bills due in 7 days)
        var sevenDaysForward = now.AddDays(7);
        var upcomingPurchases = await db.Purchases.AsNoTracking()
            .Where(p => p.TenantId == tenantId && p.Status == "Posted")
            .Include(p => p.Payments)
            .ToListAsync();

        var upcomingBillsTotal = upcomingPurchases
            .Where(p => (p.DueDate.HasValue && p.DueDate.Value <= sevenDaysForward) || (!p.DueDate.HasValue && p.PurchasedAt >= sevenDaysAgo))
            .Sum(p => Money(p.TotalAmount - p.Payments.Where(x => !x.IsReversed).Sum(x => x.Amount)));

        if (upcomingBillsTotal > 0)
        {
            insights.Add(new DashboardInsightDto(
                Id: "insight_cash_flow",
                Type: "cash_flow",
                Headline: $"{upcomingBillsTotal:N0} {currency} in supplier payables due within 7 days",
                Detail: "Plan receivables collection to maintain positive operating cash flow.",
                Trend: "neutral",
                MetricValue: upcomingBillsTotal
            ));
        }

        return ApiResult<List<DashboardInsightDto>>.Ok(insights);
    }

    public async Task<ApiResult<List<RecurringExpenseTemplateDto>>> GetRecurringExpenseTemplatesAsync(Guid tenantId, CancellationToken ct = default)
    {
        var templates = await db.RecurringExpenseTemplates.AsNoTracking()
            .Where(t => t.TenantId == tenantId)
            .OrderBy(t => t.NextDueDate)
            .ToListAsync(ct);

        return ApiResult<List<RecurringExpenseTemplateDto>>.Ok(templates.Select(MapRecurringTemplate).ToList());
    }

    public async Task<ApiResult<RecurringExpenseTemplateDto>> CreateRecurringExpenseTemplateAsync(
        Guid tenantId, Guid userId, CreateRecurringExpenseTemplateRequest request, CancellationToken ct = default)
    {
        if (request.Amount <= 0)
            return ApiResult<RecurringExpenseTemplateDto>.Fail("Amount must be greater than zero.");
        if (string.IsNullOrWhiteSpace(request.Category))
            return ApiResult<RecurringExpenseTemplateDto>.Fail("Category is required.");

        var validFrequencies = new HashSet<string>(StringComparer.OrdinalIgnoreCase) { "daily", "weekly", "monthly", "quarterly", "yearly" };
        var frequency = request.Frequency.Trim().ToLowerInvariant();
        if (!validFrequencies.Contains(frequency))
            return ApiResult<RecurringExpenseTemplateDto>.Fail("Frequency must be daily, weekly, monthly, quarterly, or yearly.");

        var currency = !string.IsNullOrWhiteSpace(request.Currency) ? request.Currency.Trim().ToUpperInvariant() : await Currency(tenantId);

        var template = new RecurringExpenseTemplate
        {
            Id = Guid.NewGuid(),
            TenantId = tenantId,
            Category = request.Category.Trim(),
            Amount = Money(request.Amount),
            Currency = currency,
            Description = Clean(request.Description),
            Frequency = frequency,
            NextDueDate = request.NextDueDate,
            IsActive = true,
            CreatedAt = DateTime.UtcNow
        };

        db.RecurringExpenseTemplates.Add(template);
        await db.SaveChangesAsync(ct);

        return ApiResult<RecurringExpenseTemplateDto>.Ok(MapRecurringTemplate(template));
    }

    public async Task<ApiResult<RecurringExpenseTemplateDto>> UpdateRecurringExpenseTemplateAsync(
        Guid tenantId, Guid templateId, UpdateRecurringExpenseTemplateRequest request, CancellationToken ct = default)
    {
        var template = await db.RecurringExpenseTemplates.FirstOrDefaultAsync(t => t.TenantId == tenantId && t.Id == templateId, ct);
        if (template == null)
            return ApiResult<RecurringExpenseTemplateDto>.Fail("Recurring expense template not found.");

        if (request.Amount.HasValue)
        {
            if (request.Amount.Value <= 0)
                return ApiResult<RecurringExpenseTemplateDto>.Fail("Amount must be greater than zero.");
            template.Amount = Money(request.Amount.Value);
        }

        if (!string.IsNullOrWhiteSpace(request.Category))
            template.Category = request.Category.Trim();

        if (!string.IsNullOrWhiteSpace(request.Frequency))
        {
            var validFrequencies = new HashSet<string>(StringComparer.OrdinalIgnoreCase) { "daily", "weekly", "monthly", "quarterly", "yearly" };
            var freq = request.Frequency.Trim().ToLowerInvariant();
            if (!validFrequencies.Contains(freq))
                return ApiResult<RecurringExpenseTemplateDto>.Fail("Frequency must be daily, weekly, monthly, quarterly, or yearly.");
            template.Frequency = freq;
        }

        if (request.NextDueDate.HasValue)
            template.NextDueDate = request.NextDueDate.Value;

        if (request.Description != null)
            template.Description = Clean(request.Description);

        if (request.IsActive.HasValue)
            template.IsActive = request.IsActive.Value;

        template.UpdatedAt = DateTime.UtcNow;
        await db.SaveChangesAsync(ct);

        return ApiResult<RecurringExpenseTemplateDto>.Ok(MapRecurringTemplate(template));
    }

    public async Task<ApiResult<bool>> DeleteRecurringExpenseTemplateAsync(Guid tenantId, Guid templateId, CancellationToken ct = default)
    {
        var template = await db.RecurringExpenseTemplates.FirstOrDefaultAsync(t => t.TenantId == tenantId && t.Id == templateId, ct);
        if (template == null)
            return ApiResult<bool>.Fail("Recurring expense template not found.");

        db.RecurringExpenseTemplates.Remove(template);
        await db.SaveChangesAsync(ct);
        return ApiResult<bool>.Ok(true);
    }

    public async Task<ApiResult<ProcessRecurringExpensesResultDto>> ProcessDueRecurringExpensesAsync(
        Guid tenantId, Guid userId, CancellationToken ct = default)
    {
        var now = DateTime.UtcNow;
        var dueTemplates = await db.RecurringExpenseTemplates
            .Where(t => t.TenantId == tenantId && t.IsActive && t.NextDueDate <= now)
            .ToListAsync(ct);

        var createdActionIds = new List<Guid>();

        foreach (var template in dueTemplates)
        {
            var idempotencyKey = $"recurring-{template.Id}-{template.NextDueDate:yyyyMMdd}";

            var existingAction = await db.AiActions
                .FirstOrDefaultAsync(a => a.TenantId == tenantId && a.IdempotencyKey == idempotencyKey, ct);

            if (existingAction == null)
            {
                var payloadObj = new
                {
                    Amount = template.Amount,
                    Category = template.Category,
                    Description = string.IsNullOrWhiteSpace(template.Description)
                        ? $"[Recurring] {template.Category}"
                        : $"[Recurring] {template.Description}"
                };

                var action = new AiAction
                {
                    Id = Guid.NewGuid(),
                    TenantId = tenantId,
                    UserId = userId,
                    Intent = "expense",
                    RiskLevel = "Financial",
                    Status = AiActionStatuses.PendingConfirmation,
                    RequiresConfirmation = true,
                    SourceText = $"Recurring expense: {template.Category} - {template.Description ?? template.Category}",
                    PayloadJson = JsonSerializer.Serialize(payloadObj),
                    IdempotencyKey = idempotencyKey,
                    CreatedAt = now,
                    ExpiresAt = now.AddDays(7)
                };

                db.AiActions.Add(action);
                createdActionIds.Add(action.Id);
            }

            // Advance NextDueDate
            template.NextDueDate = template.Frequency.ToLowerInvariant() switch
            {
                "daily" => template.NextDueDate.AddDays(1),
                "weekly" => template.NextDueDate.AddDays(7),
                "monthly" => template.NextDueDate.AddMonths(1),
                "quarterly" => template.NextDueDate.AddMonths(3),
                "yearly" => template.NextDueDate.AddYears(1),
                _ => template.NextDueDate.AddMonths(1)
            };

            while (template.NextDueDate <= now)
            {
                template.NextDueDate = template.Frequency.ToLowerInvariant() switch
                {
                    "daily" => template.NextDueDate.AddDays(1),
                    "weekly" => template.NextDueDate.AddDays(7),
                    "monthly" => template.NextDueDate.AddMonths(1),
                    "quarterly" => template.NextDueDate.AddMonths(3),
                    "yearly" => template.NextDueDate.AddYears(1),
                    _ => template.NextDueDate.AddMonths(1)
                };
            }

            template.LastGeneratedAt = now;
            template.UpdatedAt = now;
        }

        await db.SaveChangesAsync(ct);

        return ApiResult<ProcessRecurringExpensesResultDto>.Ok(new(
            ProcessedCount: dueTemplates.Count,
            DraftsCreatedCount: createdActionIds.Count,
            CreatedActionIds: createdActionIds
        ));
    }

    public async Task<ApiResult<ProductSmartDefaultsDto>> GetProductSmartDefaultsAsync(
        Guid tenantId, Guid productId, Guid? supplierId = null, CancellationToken ct = default)
    {
        var product = await db.Products.AsNoTracking()
            .FirstOrDefaultAsync(p => p.TenantId == tenantId && p.Id == productId, ct);

        if (product == null)
            return ApiResult<ProductSmartDefaultsDto>.Fail("Product not found.");

        decimal? lastCost = null;

        if (supplierId.HasValue)
        {
            var item = await db.PurchaseItems.AsNoTracking()
                .Include(pi => pi.Purchase)
                .Where(pi => pi.TenantId == tenantId && pi.ProductId == productId && pi.Purchase.SupplierId == supplierId.Value && pi.Purchase.Status != "Voided")
                .OrderByDescending(pi => pi.Purchase.PurchasedAt)
                .FirstOrDefaultAsync(ct);

            if (item != null)
                lastCost = item.UnitCost;
        }

        if (!lastCost.HasValue)
        {
            var lastGeneralItem = await db.PurchaseItems.AsNoTracking()
                .Include(pi => pi.Purchase)
                .Where(pi => pi.TenantId == tenantId && pi.ProductId == productId && pi.Purchase.Status != "Voided")
                .OrderByDescending(pi => pi.Purchase.PurchasedAt)
                .FirstOrDefaultAsync(ct);

            if (lastGeneralItem != null)
                lastCost = lastGeneralItem.UnitCost;
            else if (product.CostPrice > 0)
                lastCost = product.CostPrice;
        }

        var usualSupplierGroup = await db.PurchaseItems.AsNoTracking()
            .Include(pi => pi.Purchase)
            .Where(pi => pi.TenantId == tenantId && pi.ProductId == productId && pi.Purchase.Status != "Voided")
            .GroupBy(pi => pi.Purchase.SupplierId)
            .OrderByDescending(g => g.Count())
            .Select(g => g.Key)
            .FirstOrDefaultAsync(ct);

        Guid? usualSupplierId = usualSupplierGroup != Guid.Empty ? usualSupplierGroup : null;
        string? usualSupplierName = null;
        if (usualSupplierId.HasValue)
        {
            var sup = await db.Suppliers.AsNoTracking()
                .FirstOrDefaultAsync(s => s.TenantId == tenantId && s.Id == usualSupplierId.Value, ct);
            usualSupplierName = sup?.Name;
        }

        return ApiResult<ProductSmartDefaultsDto>.Ok(new(
            ProductId: product.Id,
            UsualSupplierId: usualSupplierId,
            UsualSupplierName: usualSupplierName,
            LastUnitCost: lastCost,
            DefaultPrice: product.DefaultPrice,
            Unit: product.Unit
        ));
    }

    public async Task<ApiResult<SupplierSmartDefaultsDto>> GetSupplierSmartDefaultsAsync(
        Guid tenantId, Guid supplierId, CancellationToken ct = default)
    {
        var supplier = await db.Suppliers.AsNoTracking()
            .FirstOrDefaultAsync(s => s.TenantId == tenantId && s.Id == supplierId, ct);

        if (supplier == null)
            return ApiResult<SupplierSmartDefaultsDto>.Fail("Supplier not found.");

        var usualMethod = await db.PurchasePayments.AsNoTracking()
            .Where(pp => pp.TenantId == tenantId && pp.SupplierId == supplierId && !pp.IsReversed)
            .GroupBy(pp => pp.Method)
            .OrderByDescending(g => g.Count())
            .Select(g => g.Key)
            .FirstOrDefaultAsync(ct);

        var terms = supplier.PaymentTermsDays ?? 0;
        var defaultDueDate = DateTime.UtcNow.Date.AddDays(terms);

        return ApiResult<SupplierSmartDefaultsDto>.Ok(new(
            SupplierId: supplier.Id,
            PaymentTermsDays: supplier.PaymentTermsDays,
            UsualPaymentMethod: usualMethod ?? "Cash",
            DefaultDueDate: defaultDueDate
        ));
    }

    private static RecurringExpenseTemplateDto MapRecurringTemplate(RecurringExpenseTemplate t) => new(
        t.Id,
        t.Category,
        t.Amount,
        t.Currency,
        t.Description,
        t.Frequency,
        t.NextDueDate,
        t.IsActive,
        t.LastGeneratedAt,
        t.CreatedAt,
        t.UpdatedAt
    );
}
